/**
 * Frame around every Fiori app (index.html?app=...):
 *  - a shell bar on top (back to launchpad, app title, the user's role and initials)
 *  - an "Authorization required" page if the user's role may not open this app
 *  - read-only mode: hides Create/Edit/Delete and workflow buttons the role may not use
 *    (the backend would refuse them anyway; hiding avoids confusing "Forbidden" errors)
 */
(function () {
    const esc = s => String(s ?? '').replace(/[&<>"']/g, c => `&#${c.charCodeAt(0)};`);   // HTML-escape text

    // Button ids generated by Fiori Elements, used to hide buttons a role may not use
    const EDIT_BUTTONS = '[id*="::StandardAction::Create"], [id*="::StandardAction::Edit"], [id*="::StandardAction::Delete"]';
    const WORKFLOW_BUTTONS = '[id*="::DataFieldForAction::"]';

    window.startAppShell = function (appId) {
        const app = window.RETCL.apps[appId];

        // 1. Shell bar (user details are filled in once we know who is signed in)
        const bar = document.createElement('header');
        bar.className = 'retclShell';
        bar.innerHTML = `
            <a class="retclShellBack" href="/index.html" title="Back to launchpad" aria-label="Back to launchpad">
                <svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true"><path d="M10.5 2.5 5 8l5.5 5.5" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>
            </a>
            <span class="retclShellLogo" aria-hidden="true">RET</span>
            <span class="retclShellTitle">${esc(app.fullTitle)}</span>
            <span class="retclShellSub">Rental Equipment Tracking</span>
            <span class="retclShellSpacer"></span>
            <span class="retclShellRole"></span>
            <span class="retclShellAvatar"></span>`;
        document.body.prepend(bar);

        // 2. Who is signed in -> role -> what this role may do in this app
        window.loadSession().then(session => {
            const roleName = session?.role || 'None';
            const role = window.RETCL.roles[roleName];
            bar.querySelector('.retclShellRole').textContent = roleName === 'None' ? 'No role assigned' : role.title;
            bar.querySelector('.retclShellAvatar').textContent = session?.initials || '?';
            bar.querySelector('.retclShellAvatar').title = session ? `${session.name} · ${session.plant}` : 'Not signed in';

            if (!window.RETCL.allows(role.apps, appId)) return showAccessDenied(session, role, appId);

            const hidden = [
                ...(!window.RETCL.allows(role.edit, appId) ? [EDIT_BUTTONS] : []),
                ...(!window.RETCL.allows(role.act, appId) ? [WORKFLOW_BUTTONS] : [])
            ];
            if (hidden.length) {
                const style = document.createElement('style');
                style.textContent = `${hidden.join(', ')} { display: none !important; }`;
                document.head.appendChild(style);
            }
        });
    };

    /** Replaces the app with a short explanation and a link back to the launchpad. */
    function showAccessDenied(session, role, appId) {
        const app = window.RETCL.apps[appId];
        const allowedRoles = Object.keys(window.RETCL.roles)
            .filter(name => name !== 'None' && window.RETCL.allows(window.RETCL.roles[name].apps, appId));
        document.body.classList.add('retclNoAccess');                              // CSS hides the app (even if it loads later)
        const box = document.createElement('div');
        box.className = 'retclDenied';
        box.innerHTML = `
            <div class="retclDeniedCard">
                <h2>Authorization required</h2>
                <p>${session ? `You are signed in as <strong>${esc(session.name)}</strong> (${esc(role.title)}).` : 'You are not signed in.'}
                   Your role does not include <strong>${esc(app.fullTitle)}</strong>.</p>
                <p class="retclDeniedRoles">Roles with access: ${esc(allowedRoles.join(', '))}</p>
                <a class="retclBtnEmph" href="/index.html">Back to launchpad</a>
            </div>`;
        document.body.appendChild(box);
    }
})();
